"use client";

import { useEffect, useState, type ReactNode } from "react";

const LINES = [
  { type: "cmd", text: "megent run --policy ./policy.yaml --agent billing-agent" },
    { type: "info", text: "  - Policy loaded | 3 rules | PII masking: ON" },
    { type: "info", text: "  - Agent identity verified (JWT exp: 3600s)" },
    { type: "info", text: "  - Watching tool calls..." },
    { type: "blank", text: "" },
    { type: "ok", text: "  ALLOW  read_invoice(id=\"INV-2041\") | 0.3ms" },
    { type: "ok", text: "  ALLOW  send_email(to=\"***@***.com\") | PII masked | 0.4ms" },
    { type: "block", text: "  BLOCK  transfer_funds(amount=14200) | not in policy" },
    { type: "block", text: "  BLOCK  delete_customer(id=\"USR-991\") | wildcard rule" },
    { type: "warn", text: "  ALERT  2 violations | logged | agent still running" },
];

export default function Hero() {
  const [shownLines, setShownLines] = useState(0);
  const [started, setStarted] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText("pip install megent");
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch (err) {
      console.error("Copy failed", err);
    }
  };

  useEffect(() => {
    const t = setTimeout(() => setStarted(true), 800);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!started) return;
    if (shownLines >= LINES.length) return;
    const delay = shownLines === 0 ? 200 : LINES[shownLines - 1].type === "blank" ? 120 : 380;
    const t = setTimeout(() => setShownLines((n) => n + 1), delay);
    return () => clearTimeout(t);
  }, [started, shownLines]);

  return (
    <section className="relative min-h-screen flex items-center overflow-hidden pt-20 lg:pt-24 bg-white">
      <div className="absolute inset-0 pointer-events-none">
        <div
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse 900px 700px at 15% -5%, rgba(79,70,229,0.07) 0%, transparent 60%)," +
              "radial-gradient(ellipse 700px 500px at 85% 10%, rgba(99,102,241,0.05) 0%, transparent 55%)," +
              "radial-gradient(ellipse 600px 400px at 50% 105%, rgba(79,70,229,0.04) 0%, transparent 55%)",
          }}
        />
        <div
          className="absolute inset-0 opacity-[0.015]"
          style={{
            backgroundImage:
              "linear-gradient(var(--border) 1px, transparent 1px), linear-gradient(90deg, var(--border) 1px, transparent 1px)",
            backgroundSize: "48px 48px",
          }}
        />
      </div>

      <div className="relative z-10 max-w-7xl mx-auto px-5 sm:px-8 w-full py-20 lg:py-28">
        <div className="grid mt-[-100px] lg:grid-cols-2 gap-12 xl:gap-20 items-center">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full border border-[var(--indigo-border)] bg-[var(--indigo-light)] mb-7 animate-[fadeUp_0.5s_0.1s_ease_both]">
              <span className="w-1.5 h-1.5 rounded-full bg-[var(--indigo)] animate-pulse2" />
              <span className="text-[12px] font-semibold text-[var(--text)]">Runtime policy for AI agents</span>
            </div>

            <h1 className="text-[clamp(44px,5.5vw,72px)] font-extrabold tracking-[-3px] leading-[1.0] text-[var(--text)] mb-6 animate-[fadeUp_0.5s_0.2s_ease_both]">
              Stop trusting
              {/* <br />
              your agents.
              <br />
              Start enforcing policy. */}
            </h1>

            <p className="text-[17px] text-[var(--text2)] leading-[1.75] max-w-lg mb-8 animate-[fadeUp_0.5s_0.3s_ease_both]">
              Megent is the policy language and runtime that sits between your app and your AI agents.
              Every tool call gets checked. Every PII field gets masked. Every violation gets logged.
            </p>

            <div className="flex flex-wrap gap-3 mb-8 animate-[fadeUp_0.5s_0.4s_ease_both]">
              <a
                href="#waitlist"
                className="inline-flex items-center gap-2 px-5 py-3 text-[14px] font-semibold text-white bg-[var(--indigo)] rounded-[30px] hover:bg-indigo-600 transition-colors shadow-card-md"
              >
                Get early access
                <ArrowRight />
              </a>
              <button
                type="button"
                onClick={handleCopy}
                className="inline-flex items-center gap-2 px-5 py-3 text-[14px] font-semibold text-[var(--indigo)] border border-[var(--indigo-border)] rounded-[30px] hover:bg-[var(--indigo-light)] transition-colors"
                aria-live="polite"
              >
                <CodeIcon />
                <span className="font-mono">{copied ? "Copied!" : "pip install megent"}</span>
              </button>
            </div>

            {/* <div className="flex flex-wrap items-center gap-3 animate-[fadeUp_0.5s_0.5s_ease_both] text-[12px] text-[var(--text3)] font-mono">
              <Badge>MIT licensed</Badge>
              <Badge>0 telemetry</Badge>
              <Badge>Under 1ms overhead</Badge>
            </div> */}
          </div>
          {/* <img src="/file_00000000064c71f5b0fbba3e7f724e69.png" alt="Megent Runtime" className="animate-[fadeUp_0.6s_0.35s_ease_both] oop" /> */}
        {/* <?xml version="1.0" encoding="utf-8"?> */}
{/* <svg width="1024" height="1536" viewBox="0 0 1024 1536" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <image id="image_1" width="1024" height="1536" href="data:image/png;base64,
    // 
    // " xmlns:p3="http://www.w3.org/1999/xlink" />
    <pattern id="pattern_2" width="2" height="2">
      <use xmlns:p4="http://www.w3.org/1999/xlink" />
    </pattern>
  </defs>
  <rect width="1024" height="1536" fill="url(#pattern_2)" fill-rule="evenodd" />
</svg> */}
<img src="/freepik__adjust__68767.jpeg" alt=""  className="animate-[fadeUp_0.6s_0.35s] cover-fit object-cover asperct-[16/9] w-[300px]"/>
        </div>
      </div>
      
    </section>
  );
}

function Badge({ children }: { children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1 px-3 py-1.5 rounded-full border border-[var(--border)] bg-white shadow-sm">
      <span className="w-1.5 h-1.5 rounded-full bg-[var(--indigo)]" />
      {children}
    </span>
  );
}

function ArrowRight() {
  return (
    <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
      <path d="M2.5 6.5h8M8 3.5l3 3-3 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function CodeIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
      <path
        d="M5 3.5 3.5 5v4L5 10.5M9 3.5 10.5 5v4L9 10.5"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}
